const todosSlice = createSlice({
  name: 'todos',
  initialState: [],
  reducers: {
    added: (state, action) => { state.push({ text: action.payload, done: false }) },
  },
})
export const { added } = todosSlice.actions
export const store = configureStore({ reducer: { todos: todosSlice.reducer } })
// component: const todos = useSelector(s => s.todos); dispatch(added('milk'))

function reducer(state, action) {
  switch (action.type) {
    case 'added': return [...state, { text: action.text, done: false }];
    default: return state;
  }
}
function StoreProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, []);
  const value = useMemo(() => ({ state, dispatch }), [state]);
  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}
